const quarantineArtifact = `-- name: QuarantineArtifact :exec
WITH target AS (
    SELECT sr.id AS result_id, sj.id AS job_id
    FROM secret_results sr
    JOIN scan_jobs sj ON sj.id = sr.scan_job_id
    JOIN artifact_refs ref ON ref.id = sj.artifact_ref_id
    WHERE sj.scan_type = 'secret' AND ref.repository_id = $3 AND ref.artifact_path = $4
), upd1 AS (
    UPDATE secret_results SET quarantined = $1
    WHERE id = (SELECT result_id FROM target)
    RETURNING id
)
UPDATE scan_jobs SET updated_at = $2 WHERE id = (SELECT job_id FROM target)
`

type QuarantineArtifactParams struct {
	Quarantined  bool      `db:"quarantined" json:"quarantined"`
	UpdatedAt    time.Time `db:"updated_at" json:"updated_at"`
	RepositoryID string    `db:"repository_id" json:"repository_id"`
	ArtifactPath string    `db:"artifact_path" json:"artifact_path"`
}

func (q *Queries) QuarantineArtifact(ctx context.Context, arg QuarantineArtifactParams) error {
	_, err := q.db.Exec(ctx, quarantineArtifact,
		arg.Quarantined,
		arg.UpdatedAt,
		arg.RepositoryID,
		arg.ArtifactPath,
	)
	return err
}

